(function(){var counters={meter:document.querySelectorAll('#pdn-meter-table tbody tr').length,payment:document.querySelectorAll('#pdn-payment-table tbody tr').length,income:document.querySelectorAll('#pdn-income-table tbody tr').length,customer:document.querySelectorAll('#pdn-customer-table tbody tr').length,'other-sale':document.querySelectorAll('#pdn-other-sale-table tbody tr').length};document.querySelectorAll('[data-pdn-form-tab]').forEach(function(a){a.addEventListener('click',function(e){e.preventDefault();document.querySelectorAll('[data-pdn-form-tab]').forEach(x=>x.classList.remove('active'));a.classList.add('active');document.querySelectorAll('[data-pdn-panel]').forEach(p=>p.style.display=p.dataset.pdnPanel===a.dataset.pdnFormTab?'block':'none');});});function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));}function options(rows,label,id,selected){return '<option value="">Select</option>'+rows.map(r=>'<option value="'+esc(r[id||'id'])+'"'+(String(selected)===String(r[id||'id'])?' selected':'')+'>'+esc(r[label||'name'])+'</option>').join('');}document.addEventListener('click',function(e){var remove=e.target.closest('.pdn-remove');if(remove){remove.closest('tr').remove();return;}var add=e.target.closest('[data-pdn-add]');if(!add)return;var t=add.dataset.pdnAdd,i=counters[t]++,d=window.PDIRECTNEW_FORM_DATA||{},html='';if(t==='meter'){html='<tr><td><select name="meter_sales['+i+'][pump_id]" class="form-control">'+options(d.pumps,'name')+'</select></td><td><select name="meter_sales['+i+'][product_id]" class="form-control">'+options(d.products,'name')+'</select></td><td><input type="number" step="0.001" name="meter_sales['+i+'][opening_meter]" class="form-control pdn-opening" value="0"></td><td><input type="number" step="0.001" name="meter_sales['+i+'][closing_meter]" class="form-control pdn-closing" value="0"></td><td><input type="number" step="0.001" name="meter_sales['+i+'][testing_qty]" class="form-control pdn-testing" value="0"></td><td><input readonly class="form-control pdn-sold" value="0"></td><td><input type="number" step="0.0001" name="meter_sales['+i+'][unit_price]" class="form-control pdn-price" value="0"></td><td><input type="number" step="0.0001" name="meter_sales['+i+'][discount_value]" class="form-control pdn-discount" value="0"></td><td><input readonly class="form-control pdn-amount" value="0"></td><td><button type="button" class="btn btn-danger pdn-remove">×</button></td></tr>';document.querySelector('#pdn-meter-table tbody').insertAdjacentHTML('beforeend',html);}else if(t==='payment'){html='<tr><td><select name="payments['+i+'][payment_type]" class="form-control"><option>cash</option><option>card</option><option>cheque</option><option>credit_sale</option><option>expense</option><option>shortage</option><option>excess</option></select></td><td><input name="payments['+i+'][reference_no]" class="form-control"></td><td><select name="payments['+i+'][contact_id]" class="form-control">'+options(d.contacts,'name')+'</select></td><td><select name="payments['+i+'][account_id]" class="form-control">'+options(d.accounts,'name')+'</select></td><td><input type="number" step="0.0001" name="payments['+i+'][amount]" class="form-control" value="0"></td><td><button type="button" class="btn btn-danger pdn-remove">×</button></td></tr>';document.querySelector('#pdn-payment-table tbody').insertAdjacentHTML('beforeend',html);}else if(t==='other-sale'){html='<tr><td><input name="other_sales['+i+'][reference_no]" class="form-control"></td><td><select name="other_sales['+i+'][contact_id]" class="form-control">'+options(d.contacts,'name')+'</select></td><td><select name="other_sales['+i+'][lines][0][product_id]" class="form-control">'+options(d.products,'name')+'</select></td><td><input type="number" step="0.0001" name="other_sales['+i+'][lines][0][qty]" class="form-control" value="1"></td><td><input type="number" step="0.0001" name="other_sales['+i+'][lines][0][unit_price]" class="form-control" value="0"></td><td><button type="button" class="btn btn-danger pdn-remove">×</button></td></tr>';document.querySelector('#pdn-other-sale-table tbody').insertAdjacentHTML('beforeend',html);}else if(t==='income'){html='<tr><td><input name="other_income['+i+'][description]" class="form-control"></td><td><select name="other_income['+i+'][account_id]" class="form-control">'+options(d.accounts,'name')+'</select></td><td><input type="number" step="0.0001" name="other_income['+i+'][amount]" class="form-control" value="0"></td><td><button type="button" class="btn btn-danger pdn-remove">×</button></td></tr>';document.querySelector('#pdn-income-table tbody').insertAdjacentHTML('beforeend',html);}else{html='<tr><td><select name="customer_payments['+i+'][contact_id]" class="form-control">'+options(d.contacts,'name')+'</select></td><td><input name="customer_payments['+i+'][reference_no]" class="form-control"></td><td><select name="customer_payments['+i+'][payment_method]" class="form-control"><option>cash</option><option>card</option><option>cheque</option><option>bank_transfer</option></select></td><td><input type="number" step="0.0001" name="customer_payments['+i+'][amount]" class="form-control" value="0"></td><td><button type="button" class="btn btn-danger pdn-remove">×</button></td></tr>';document.querySelector('#pdn-customer-table tbody').insertAdjacentHTML('beforeend',html);}});document.addEventListener('input',function(e){if(!e.target.closest('#pdn-meter-table'))return;var tr=e.target.closest('tr'),op=parseFloat(tr.querySelector('.pdn-opening').value)||0,cl=parseFloat(tr.querySelector('.pdn-closing').value)||0,te=parseFloat(tr.querySelector('.pdn-testing').value)||0,pr=parseFloat(tr.querySelector('.pdn-price').value)||0,di=parseFloat(tr.querySelector('.pdn-discount').value)||0,so=Math.max(0,cl-op-te);tr.querySelector('.pdn-sold').value=so.toFixed(3);tr.querySelector('.pdn-amount').value=Math.max(0,so*pr-di).toFixed(4);});})();
